def count_islands(grid):
    if not grid or not grid[0]:
        return 0
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                count += 1
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1 and not visited[nr][nc]:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
    return count

def distinct_value_count(grid):
    values = set()
    for row in grid:
        values.update(row)
    return len(values)

def is_point_symmetric(grid):
    rows = len(grid)
    if rows == 0:
        return True
    cols = len(grid[0])
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != grid[rows - 1 - i][cols - 1 - j]:
                return False
    return True

def border_sum(grid):
    if not grid or not grid[0]:
        return 0
    rows = len(grid)
    cols = len(grid[0])
    total = 0
    for r in range(rows):
        for c in range(cols):
            if r == 0 or r == rows - 1 or c == 0 or c == cols - 1:
                total += grid[r][c]
    return total

def count_palindrome_rows(grid):
    count = 0
    for row in grid:
        if row == row[::-1]:
            count += 1
    return count

def count_palindrome_columns(grid):
    if not grid or not grid[0]:
        return 0
    cols = len(grid[0])
    count = 0
    for c in range(cols):
        col = [row[c] for row in grid]
        if col == col[::-1]:
            count += 1
    return count

def multiply_matrices(a, b):
    rows_a = len(a)
    cols_a = len(a[0]) if rows_a > 0 else 0
    cols_b = len(b[0]) if len(b) > 0 else 0
    result = [[0] * cols_b for _ in range(rows_a)]
    for i in range(rows_a):
        for j in range(cols_b):
            total = 0
            for k in range(cols_a):
                total += a[i][k] * b[k][j]
            result[i][j] = total
    return result

def find_value_position(grid, target):
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == target:
                return (r, c)
    return None
